import random

import torch


def gen_inputs(ctx, device):
    shape = ctx["x__shape"]
    n = 1
    for s in shape:
        n *= int(s)
    rng = random.Random(2024)
    return {"x": [rng.randint(-1000, 1000) for _ in range(n)]}


def run(x):
    return torch.ops.aten._list_to_tensor(x)
